// src/jsx/Contacts.jsx
import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import {
    collection,
    query,
    where,
    getDoc,
    getDocs,
    doc,
    setDoc,
    serverTimestamp,
    onSnapshot
} from "firebase/firestore";
import Avatar from "./Avatar";
import useSearchUsers from "../hooks/useSearchUsers";

export default function Contacts({
    currentUser,
    setChatUser,
    setChatGroup,
    setScreen,
    logout
}) {
    const { allUsers } = useSearchUsers();

    const [contacts, setContacts] = useState([]);
    const [recentChats, setRecentChats] = useState([]);
    const [searchAdd, setSearchAdd] = useState("");
    const [searchResults, setSearchResults] = useState([]);
    const [showAddModal, setShowAddModal] = useState(false);

    // ============================
    // 1. CARREGAR CONTATOS
    // ============================
    useEffect(() => {
        const ref = collection(db, `users/${currentUser.uid}/contacts`);
        const unsub = onSnapshot(ref, snap => {
            setContacts(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        });
        return () => unsub();
    }, [currentUser.uid]);

    // ============================
    // 2. CARREGAR CHATS RECENTES
    // ============================
    useEffect(() => {
        const roomsRef = collection(db, "rooms");
        const q = query(
            roomsRef,
            where("members", "array-contains", currentUser.uid)
        );

        const unsub = onSnapshot(q, snap => {
            const arr = snap.docs
                .map(d => ({ id: d.id, ...d.data() }))
                .sort((a, b) => {
                    if (!a.lastUpdated) return 1;
                    if (!b.lastUpdated) return -1;
                    return b.lastUpdated.seconds - a.lastUpdated.seconds;
                });

            setRecentChats(arr);
        });

        return () => unsub();
    }, [currentUser.uid]);


    // ======================================================
    // 3. BUSCA PARA ADICIONAR NOVO CONTATO
    // ======================================================
    const searchUsersToAdd = () => {
        const s = searchAdd.toLowerCase().trim();
        if (!s) return setSearchResults([]);

        const filtered = allUsers.filter(u =>
            u.id !== currentUser.uid &&
            (
                (u.nome || "").toLowerCase().includes(s) ||
                (u.email || "").toLowerCase().includes(s) ||
                u.id.toLowerCase().includes(s)
            )
        );

        setSearchResults(filtered);
    };

    // ======================================================
    // 4. CRIAR ROOM + ADICIONAR CONTATO
    // ======================================================
    async function addContactAndCreateRoom(userB) {
        const userA = currentUser;
        const contactRef = doc(db, `users/${userA.uid}/contacts/${userB.id}`);

        // 4.1 Adicionar contato
        await setDoc(contactRef, {
            id: userB.id,
            nome: userB.nome || userB.email,
            email: userB.email,
            avatarUrl: userB.avatarUrl || "",
            addedAt: serverTimestamp()
        });

        // 4.2 Criar Room
        const roomId = [userA.uid, userB.id].sort().join("_");
        const roomRef = doc(db, "rooms", roomId);
        const roomSnap = await getDoc(roomRef);

        if (!roomSnap.exists()) {
            await setDoc(roomRef, {
                id: roomId,
                members: [userA.uid, userB.id],
                createdAt: serverTimestamp(),
                lastMessage: "",
                lastUpdated: serverTimestamp()
            });
        }

        // 4.3 Abrir o chat
        setChatUser(userB);
        setChatGroup(null);
        setScreen("private");
        setShowAddModal(false);
        setSearchAdd("");
        setSearchResults([]);
    }

    return (
        <div className="sidebar">

            {/* ================= HEADER ================= */}
            <div className="sidebar-header">
                <span>Olá, {currentUser.email}</span>
                <button className="logout-btn" onClick={logout}>Sair</button>
            </div>

            {/* ================= BOTÃO ADICIONAR ================= */}
            <button
                className="create-group-btn"
                style={{ marginBottom: 10 }}
                onClick={() => setShowAddModal(true)}
            >
                + Adicionar Contato
            </button>

            {/* ================= CONTATOS ================= */}
            <h3 className="section-title">Contatos</h3>

            {contacts.length === 0 && (
                <p style={{ fontSize: 12, color: "#777" }}>
                    Nenhum contato adicionado ainda.
                </p>
            )}

            {contacts.map(c => (
                <div
                    key={c.id}
                    className="contact-item"
                    onClick={() => {
                        setChatUser(c);
                        setChatGroup(null);
                        setScreen("private");
                    }}
                    style={{ display: "flex", alignItems: "center", gap: 12 }}
                >
                    <Avatar user={c} size={44} />
                    <div>
                        <div style={{ fontWeight: 600 }}>{c.nome}</div>
                        <div style={{ fontSize: 12, color: "#666" }}>{c.email}</div>
                    </div>
                </div>
            ))}

            {/* ================= CHATS RECENTES ================= */}
            <h3 className="section-title">Conversas Recentes</h3>

            {recentChats.map(chat => {
                const otherId = chat.members.find(id => id !== currentUser.uid);
                const otherUser = allUsers.find(u => u.id === otherId);

                if (!otherUser) return null;

                return (
                    <div
                        key={chat.id}
                        className="contact-item"
                        onClick={() => {
                            setChatUser(otherUser);
                            setChatGroup(null);
                            setScreen("private");
                        }}
                        style={{ display: "flex", alignItems: "center", gap: 12 }}
                    >
                        <Avatar user={otherUser} size={44} />
                        <div>
                            <div style={{ fontWeight: 600 }}>
                                {otherUser.nome || otherUser.email}
                            </div>
                            <div style={{ fontSize: 12, color: "#666" }}>
                                {chat.lastMessage || "Iniciar conversa"}
                            </div>
                        </div>
                    </div>
                );
            })}

            {/* ==========================================================
                   MODAL DE ADICIONAR CONTATO
               ========================================================== */}
            {showAddModal && (
                <div className="modal-backdrop">
                    <div className="modal-content">
                        <h2>Adicionar Contato</h2>

                        <input
                            placeholder="Buscar por nome, email ou ID"
                            value={searchAdd}
                            onChange={e => setSearchAdd(e.target.value)}
                            onKeyUp={searchUsersToAdd}
                            style={{ marginBottom: 10 }}
                        />

                        {searchResults.map(u => (
                            <div
                                key={u.id}
                                className="contact-item"
                                style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: 12,
                                    cursor: "pointer"
                                }}
                                onClick={() => addContactAndCreateRoom(u)}
                            >
                                <Avatar user={u} size={44} />
                                <div>
                                    <div style={{ fontWeight: 600 }}>
                                        {u.nome || u.email}
                                    </div>
                                    <div style={{ fontSize: 12, color: "#666" }}>
                                        {u.email}
                                    </div>
                                </div>
                            </div>
                        ))}

                        <button
                            className="logout-btn"
                            style={{ marginTop: 20 }}
                            onClick={() => setShowAddModal(false)}
                        >
                            Fechar
                        </button>

                    </div>
                </div>
            )}
        </div>
    );
}
